1	import java.util.*;
2	
3	/**
4	 * This class collects and provides some statistical data on the state 
5	 * of a field. It is flexible: it will create and maintain a counter 
6	 * for any class of object that is found within the field.
7	 *
8	 * @version 2022.03.3
9	 */
10	public class FieldStats
11	{
12	    // Counters for each type of entity (coyote, rabbit, etc.) in the simulation.
13	    private HashMap<Class, Counter> counters;
14	    private Counter diseaseCounter;
15	    // Whether the counters are currently up to date.
16	    private boolean countsValid;
17	
18	    /**
19	     * Construct a FieldStats object.
20	     */
21	    public FieldStats()
22	    {
23	        // Set up a collection for counters for each type of animal that
24	        // we might find
25	        counters = new HashMap<>();
26	        diseaseCounter = new Counter("Diseased");
27	        countsValid = true;
28	    }
29	
30	    /**
31	     * Get details of what is in the field.
32	     * @return A string describing what is in the field.
33	     */
34	    public String getPopulationDetails(Field field)
35	    {
36	        StringBuffer buffer = new StringBuffer();
37	        if(!countsValid) {
38	            generateCounts(field);
39	        }
40	        for(Class key : counters.keySet()) {
41	            Counter info = counters.get(key);
42	            buffer.append(info.getName());
43	            buffer.append(": ");
44	            buffer.append(info.getCount());
45	            buffer.append(' ');
46	        }
47	        // displaying the number of diseased animals
48	        buffer.append(" | ");
49	        buffer.append(getDiseasedPopulation());
50	        return buffer.toString();
51	    }
52	
53	    public int getCount(Class cls)
54	    {
55	        Counter count = counters.get(cls);
56	        if(count != null){
57	            return count.getCount();
58	        }
59	        return 0;
60	    }
61	
62	    public String getCountDetails(Class cls)
63	    {
64	        return cls.getName() + ": " + getCount(cls);
65	    }
66	    
67	    /**
68	     * Invalidate the current set of statistics; reset all 
69	     * counts to zero.
70	     */
71	    public void reset()
72	    {
73	        countsValid = false;
74	        for(Class key : counters.keySet()) {
75	            Counter count = counters.get(key);
76	            count.reset();
77	        }
78	        diseaseCounter.reset();
79	    }
80	
81	    /**
82	     * Increment the count for one class of animal.
83	     * @param animalClass The class of animal to increment.
84	     */
85	    public void incrementCount(Class animalClass)
86	    {
87	        Counter count = counters.get(animalClass);
88	        if(count == null) {
89	            // We do not have a counter for this species yet.
90	            // Create one.
91	            count = new Counter(animalClass.getName());
92	            counters.put(animalClass, count);
93	        }
94	        count.increment();
95	    }
96	
97	    /**
98	     * Increment the count for number of infencted animals.
99	     */
100	    public void incrementDiseasedCount()
101	    {
102	        diseaseCounter.increment();
103	    }
104	
105	    /**
106	     * Returns a string containing the current number of infected animals.
107	     * @return A string containing the current number of infected animals.
108	     */
109	    public String getDiseasedPopulation()
110	    {
111	        return  "Diseased: " + diseaseCounter.getCount();
112	    }
113	
114	    /**
